public class Main {
    public static void main(String[] args) {
        String text = "attack at dawn";
        StringBuilder result = new StringBuilder();
        for (char c : text.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                result.append((char) ('a' + (c - 'a' + 5) % 26));
            } else {
                result.append(c);
            }
        }
        System.out.println(result);
    }
}
